export const LEGACY_CARD_PETITION_IDS = [ROYAL_TAX_PETITION_ID, HEIR_CHOICE_PETITION_ID, BOROUGH_AUTONOMY_PETITION_ID, LEGACY_CHOICE_PETITION_ID] as const;
